/* Group G05 mastery bank: Sleep and dreaming (optional); Language, thought and communication (optional). Original questions, not copied from past papers. */
(function () {
  'use strict';
  var B = window.MASTERY_BANKS = window.MASTERY_BANKS || {};
  var R = window.Mastery;
  function pick(a) { return a[Math.floor(Math.random() * a.length)]; }
  function mc(skill, q, ok, bad, why, x) {
    var it = { skill: skill, kind: 'mcq', q: q, options: [ok].concat(bad), answer: 0, why: why };
    if (x) for (var k in x) it[k] = x[k];
    return it;
  }
  function ms(skill, q, oks, bad, why, x) {
    var a = []; for (var i = 0; i < oks.length; i++) a.push(i);
    var it = { skill: skill, kind: 'multi', q: q, options: oks.concat(bad), answers: a, why: why };
    if (x) for (var k in x) it[k] = x[k];
    return it;
  }

  B['PSY-SLP-05'] = { title: 'Sleep disorders: insomnia and narcolepsy', items: [
    mc('identify disorder', 'Rosa goes to bed at 10 pm but lies awake for hours. When she does sleep she wakes at 4 am and cannot get back to sleep. Which sleep disorder fits her symptoms?', 'Insomnia', ['Narcolepsy', 'Cataplexy', 'Sleep talking'], 'Difficulty getting to sleep and waking too early are the symptoms of insomnia. Narcolepsy is the opposite problem: being unable to stay awake.'),
    mc('identify disorder', 'Tomasz falls asleep suddenly in the middle of a conversation at lunchtime. When he laughs hard, his knees give way and he collapses. Which sleep disorder fits?', 'Narcolepsy', ['Insomnia', 'Sleep walking', 'Night terrors'], 'Sudden sleep attacks in the day and a sudden loss of muscle control (cataplexy) are symptoms of narcolepsy.'),
    mc('symptoms', 'Which of these is a symptom of narcolepsy?', 'Sudden attacks of sleep at inappropriate times', ['Lying awake for several hours when trying to go to bed', 'Waking too early and not sleeping again', 'Finding it hard to relax and switch off at bedtime'], 'Narcolepsy involves excessive daytime sleepiness and sudden sleep attacks. The other three options are symptoms of insomnia.'),
    mc('symptoms', 'Which of these is a symptom of insomnia?', 'Waking in the night and not feeling refreshed', ['Collapsing suddenly when feeling strong emotion', 'Falling asleep suddenly during the day', 'Excessive sleepiness with sudden sleep attacks'], 'Insomnia means difficulty getting to sleep or staying asleep, so the person does not feel refreshed. Cataplexy and sudden sleep attacks belong to narcolepsy.'),
    mc('cataplexy', 'What is meant by <b>cataplexy</b> in people with narcolepsy?', 'A sudden loss of muscle control while awake', ['A long period of unbroken deep sleep during the night', 'Waking up too early in the morning', 'A fear of going to sleep at night'], 'Cataplexy is a sudden loss of muscle control, often triggered by strong emotion, and may occur in narcolepsy.'),
    mc('hypocretin', 'Narcolepsy has been linked to low levels of which brain chemical?', 'Hypocretin (orexin)', ['Melatonin', 'Adrenaline', 'Serotonin'], 'Low hypocretin (orexin) is associated with the brain failing to regulate wakefulness. Melatonin is the hormone that makes us sleepy, not the chemical linked to narcolepsy.'),
    ms('effects of insomnia', 'Which of these are effects of <b>insomnia</b> on daily life?', ['Poor concentration', 'Irritability', 'Making mistakes at work'], ['Sudden collapse when laughing', 'Falling asleep without warning'], 'Lack of good sleep causes tiredness, irritability, poor concentration and memory and mistakes. Sudden collapse and sleep attacks belong to narcolepsy.'),
    ms('explanations of insomnia', 'Which of these are possible explanations of <b>insomnia</b>?', ['Stress and anxiety', 'Drinking caffeine late in the day', 'Physical or mental illness such as depression'], ['Low hypocretin levels', 'Sudden loss of muscle control'], 'Insomnia can be linked to stress and anxiety, caffeine, poor sleep habits or another illness (secondary insomnia). Low hypocretin is linked to narcolepsy instead.'),
    mc('distinguishing', 'Which statement best separates the two disorders?', 'Insomnia is being unable to sleep; narcolepsy is being unable to stay awake', ['Insomnia is falling asleep suddenly; narcolepsy is lying awake all night in bed', 'Insomnia affects children only; narcolepsy affects adults only', 'Insomnia is a lack of hypocretin; narcolepsy is too much caffeine'], 'The key contrast is cannot sleep (insomnia) versus cannot stay awake (narcolepsy). Learning this stops the two being swapped.'),
    mc('application', 'Ines has had insomnia for months. At her accounting job she keeps entering figures incorrectly. Which is the best explanation of her mistakes?', 'Poor sleep leaves her tired with poor concentration', ['Sudden sleep attacks make her fall asleep during a task', 'She has lost control of her muscles while working', 'Her body is releasing too much hypocretin'], 'Insomnia leaves a person tired, so concentration and memory suffer and mistakes follow. Linking the symptom to Ines is what earns the mark.'),
    mc('definition', 'What is meant by <b>secondary insomnia</b>?', 'Insomnia caused by another physical or mental illness', ['A short spell of insomnia that lasts only a single night', 'Insomnia caused by sleeping during the day', 'Insomnia that begins only in older age'], 'Secondary insomnia is sleeplessness that is a result of something else, such as depression or a painful physical illness.'),
    mc('explanations of insomnia', 'Callum drinks four strong coffees in the evening and then cannot get to sleep until 3 am. Which explanation of insomnia best fits?', 'Caffeine is keeping his body alert', ['His brain has too little hypocretin', 'He is having cataplexy attacks', 'He has the sleep disorder narcolepsy'], 'Caffeine is a stimulant and is a recognised cause of difficulty getting to sleep. Narcolepsy and hypocretin do not explain trouble falling asleep.'),
    mc('symptoms', 'Which symptom would be found in <b>insomnia</b> but NOT in narcolepsy?', 'Waking too early and unable to sleep again', ['Sudden attacks of sleep during the day', 'Collapsing suddenly when feeling excited', 'Feeling excessively sleepy in the daytime'], 'Waking early and being unable to return to sleep is insomnia. The other symptoms describe narcolepsy.'),
    mc('definition', 'What is a <b>sleep disorder</b>?', 'A lasting problem with the amount or quality of sleep', ['Any night when a person sleeps for less than eight hours', 'A dream that a person finds hard to remember', 'The normal need to sleep more when ill'], 'A sleep disorder is more than one bad night: the sleep problem is lasting and gets in the way of everyday life.'),
    mc('effects of narcolepsy', 'Stefan has narcolepsy and is learning to drive. Which problem is most directly linked to his disorder?', 'He might fall asleep at the wheel', ['He cannot fall asleep at night', 'He wakes at 4 am and stays awake', 'He becomes too anxious to sleep'], 'Narcolepsy causes sudden sleep attacks at inappropriate times, which makes activities such as driving dangerous.'),
    mc('misconceptions', 'Which statement about narcolepsy is correct?', 'It is more than tiredness, as it includes sudden sleep attacks', ['It is simply feeling very tired after one or two nights of poor sleep', 'It means being unable to fall asleep at bedtime', 'It is caused by too much hypocretin in the brain'], 'Narcolepsy is excessive daytime sleepiness with sudden sleep attacks. It is linked to too little hypocretin, not too much.'),
    mc('application', 'Mei is told by her doctor that her brain is not regulating wakefulness properly and her hypocretin levels are low. Which disorder does she most likely have?', 'Narcolepsy', ['Insomnia', 'Secondary insomnia', 'A caffeine problem'], 'Low hypocretin (orexin) and poor regulation of wakefulness are associated with narcolepsy.'),
    mc('explanations of insomnia', 'Before her final exams, Dalia worries all night about failing and cannot get to sleep. Which explanation of insomnia applies?', 'Stress and anxiety', ['Low hypocretin levels', 'Cataplexy', 'Narcolepsy'], 'Worry and anxiety keep the mind alert, which makes getting to sleep hard. This is the stress and anxiety explanation of insomnia.'),
    ms('explanations of insomnia', 'Which of these count as <b>poor sleep habits</b> that could lead to insomnia?', ['Using a bright tablet in bed until 1 am', 'Going to bed at very different times each night'], ['Keeping the bedroom dark and quiet', 'Going to bed at the same time each night', 'Winding down with a book before bed'], 'Screens in bed and an irregular bedtime make sleep harder. A regular routine and a calm, dark room support good sleep.'),
    mc('application', 'Sam suddenly falls asleep at his desk in the afternoon. Lena lies awake in bed every night until dawn. Which pairing is correct?', 'Sam may have narcolepsy and Lena may have insomnia', ['Sam may have insomnia and Lena may have narcolepsy', 'Both may have narcolepsy', 'Neither could have a sleep disorder'], 'Sudden daytime sleep points to narcolepsy; being unable to sleep at night points to insomnia. Matching the symptom to the person is the skill.'),
    mc('matching', 'Which pair correctly matches the disorder with its main feature?', 'Narcolepsy: sudden attacks of sleep; insomnia: difficulty getting to sleep', ['Narcolepsy: difficulty getting to sleep; insomnia: sudden attacks of sleep', 'Narcolepsy: waking too early; insomnia: cataplexy', 'Narcolepsy: poor sleep habits; insomnia: low hypocretin'], 'Narcolepsy features sudden sleep attacks (and sometimes cataplexy) while insomnia is trouble getting or staying asleep.'),
    mc('effects of insomnia', 'Arjun has had insomnia for weeks and now snaps at his colleagues over small things. Which effect of insomnia does this show?', 'Irritability', ['Cataplexy', 'Sudden sleep attacks', 'Low hypocretin'], 'Irritability is a recognised effect of too little sleep. The other options are features of narcolepsy.'),
    mc('application', 'A teacher notices that Jamal falls asleep suddenly in lessons without any warning, even after a full night of sleep. Why is this unlikely to be insomnia?', 'Insomnia is trouble sleeping at night, not sudden sleep by day', ['Insomnia only ever affects people who are over 60 years old', 'Insomnia always causes a sudden loss of muscle control', 'Insomnia is caused by having high hypocretin levels'], 'Insomnia is difficulty sleeping at night; sudden sleep attacks during the day point to narcolepsy.')
  ] };

  B['PSY-SLP-08'] = { title: 'Activation Synthesis Theory of dreaming', items: [
    mc('theory basics', 'Who proposed the Activation Synthesis Theory of dreaming?', 'Hobson and McCarley (1977)', ['Freud (1900)', 'Siffre (1975)', 'Piaget (1950)'], 'Activation synthesis is the biological theory of Hobson and McCarley (1977). Freud proposed the meaning-based theory.'),
    mc('random activation', 'In Activation Synthesis Theory, which part of the brain sends random signals up to the cortex during REM sleep?', 'The brainstem (pons)', ['The pineal gland', 'The cerebellum', 'The retina'], 'The theory says the pons in the brainstem fires random signals during REM sleep. The pineal gland releases melatonin and is not the source of dream signals.'),
    mc('synthesis', 'What does the <b>synthesis</b> part of the theory mean?', 'The cortex tries to make sense of the random signals as a story', ['The brain blocks all sound and light during REM sleep', 'The body is paralysed so that dreams cannot be acted out during sleep', 'Dreams disguise hidden wishes from the unconscious'], 'Synthesis is the cortex weaving the random signals, memories and images into a dream story. The other options are sensory blockade, movement inhibition and Freud.'),
    mc('sensory blockade', 'Hira dreams she is sitting on a sunny beach while heavy rain is hammering on her bedroom window. Which part of the theory best explains why the rain does not appear in her dream?', 'Sensory blockade', ['Movement inhibition', 'Latent content', 'Dreamwork'], 'During REM the brain blocks most incoming sensory information, so the dream is not shaped by the outside world such as the rain.'),
    mc('movement inhibition', 'Omar dreams he is sprinting a race, but in his bed his body stays still. Which part of the theory explains this?', 'Movement inhibition', ['Random activation', 'Sensory blockade', 'Wish fulfilment'], 'Signals to the muscles are blocked in REM sleep, so the body is paralysed and does not act out the dream.'),
    mc('synthesis', 'Wen dreams of a giraffe teaching her maths class. According to Activation Synthesis Theory, why was the dream so odd?', 'The cortex tried to link random signals into a story', ['Her unconscious disguised a hidden wish', 'Her muscles were free to move during REM', 'Sensory information from the room around her was shaping it'], 'Random signals from the brainstem contain unrelated images and memories, so when the cortex weaves them together the story is often bizarre.'),
    mc('theory basics', 'According to Activation Synthesis Theory, what is the cause of dreams?', 'Biological activity in the brain during REM sleep', ['Repressed wishes in the unconscious mind', 'Light affecting the pineal gland', 'Events from the previous day being rehearsed and stored'], 'The theory is biological: dreams arise from brain activity in REM sleep and do not have a hidden meaning.'),
    mc('strengths', 'Which is a genuine <b>strength</b> of Activation Synthesis Theory?', 'It is based on measurable brain activity such as EEG recordings', ['It explains the hidden meaning behind every single dream a person has', 'It explains why the same dream recurs', 'It was based on detailed therapy sessions'], 'The theory links dreaming to REM sleep activity that can be measured scientifically. Meaning-based explanations are what the theory does not offer.'),
    mc('weaknesses', 'Noor has the same dream of missing a bus every month, and each time it happens when she is worried about her job. Which weakness of Activation Synthesis Theory does this show?', 'It struggles to explain recurring, meaningful dreams', ['It cannot explain why dreams are bizarre', 'It ignores the link between REM and dreaming', 'It relies on a single case study'], 'If activation is random, a dream should not repeat or relate to real worries. The theory has difficulty explaining this.'),
    mc('contrast with Freud', 'Which idea belongs to Freud, NOT to Activation Synthesis Theory?', 'Dreams contain hidden latent content', ['Dreams involve random activation', 'Sensory information is blocked in REM', 'The body is paralysed during dreaming'], 'Latent content is Freud\'s hidden meaning. Activation synthesis says dreams have no hidden meaning.'),
    ms('components', 'Which of these are parts of Activation Synthesis Theory?', ['Random activation', 'Sensory blockade', 'Movement inhibition'], ['Dreamwork', 'Latent content'], 'The three parts are random activation, sensory blockade and movement inhibition. Dreamwork and latent content are Freudian terms.'),
    ms('evaluation', 'Which of these are valid <b>evaluation points</b> about Activation Synthesis Theory?', ['It is supported by measurable brain activity', 'It explains why dreams are often bizarre', 'It struggles to explain meaningful or recurring dreams'], ['Its ideas cannot be tested because they are hidden', 'It depends on a therapist interpreting symbols'], 'The first three are genuine strengths and a weakness of this theory. Untestable interpretation of symbols is the criticism made of Freud\'s theory.'),
    mc('application', 'A researcher records a sleeper\'s brain and muscles. The brainstem is highly active, but the muscle recording is flat. Which part of the theory does the flat muscle recording support?', 'Movement inhibition', ['Sensory blockade', 'Synthesis', 'Secondary elaboration'], 'A flat muscle recording while the brain is active shows signals to the muscles are blocked, which is movement inhibition.'),
    mc('synthesis', 'Tariq dreams of his friend with the face of his teacher. The cortex joining unrelated images into one scene is called:', 'Synthesis', ['Sensory blockade', 'Movement inhibition', 'Wish fulfilment'], 'Synthesis is the cortex combining random signals and stored memories into one dream. Wish fulfilment belongs to Freud\'s theory, not this one.'),
    mc('theory basics', 'Which sentence about the activation part and the synthesis part of the theory is correct?', 'Activation is the random signal; synthesis is making sense of it', ['Activation is making sense of it; synthesis is the random signal', 'Activation is paralysis; synthesis is sensory blockade', 'Activation is hidden meaning; synthesis is disguise'], 'The brainstem produces random activation; the cortex then synthesises it into a story.'),
    mc('weaknesses', 'Much of the biological evidence behind Activation Synthesis Theory comes from animal brains. Why is this a weakness?', 'The findings may not apply to humans', ['It proves that dreams have a hidden meaning', 'It shows REM sleep is not linked to dreams', 'It means the study used too many participants'], 'Animals may not dream or process signals like humans, so generalising to humans is questionable.'),
    mc('contrast with Freud', 'Dev says his dream about an old teacher means he is secretly anxious about exams. What would a supporter of Activation Synthesis Theory most likely say?', 'The teacher appeared because random signals triggered a memory', ['The teacher is a symbol for a wish he has repressed since childhood', 'The dream shows the dreamwork at work', 'The latent content reveals his anxiety'], 'Activation synthesis denies hidden meaning: the memory was randomly activated and the cortex wove it into the dream.'),
    mc('purpose', 'What is the effect of <b>movement inhibition</b> according to the theory?', 'The body is paralysed so the dream is not acted out', ['The brain blocks sounds and light from reaching it', 'The cortex invents a story from random signals', 'The dreamer forgets the dream on waking'], 'Movement inhibition blocks signals to the muscles, which protects the sleeper from acting out dreams.'),
    mc('theory basics', 'Which statement about Activation Synthesis Theory is correct?', 'Dreams have a biological cause, not a hidden meaning', ['Dreams are caused by unconscious wishes that have been repressed', 'Dreams occur only in deep NREM sleep', 'Dreams are the result of outside noises'], 'The theory ties dreaming to REM sleep and brain activity, not to any hidden message.'),
    mc('application', 'Lucia remembers vivid dreams when woken during REM sleep but rarely when woken from deep non-REM sleep. Which idea in the theory does this fit best?', 'Dreams arise from the brain activity of REM sleep', ['Dreams are caused by the pineal gland releasing melatonin', 'Dreams are disguised wishes from the unconscious', 'Dreams are a response to outside sounds'], 'Activation synthesis links dreaming to the activation of the brain in REM sleep.'),
    mc('sensory blockade', 'Which description of <b>sensory blockade</b> is correct?', 'Most incoming information from the senses is blocked in REM sleep', ['The muscles are prevented from moving during REM sleep to stop acting out', 'The cortex invents a story from random signals', 'Dreams are shaped by what the dreamer saw that day'], 'Sensory blockade stops most input from the senses reaching the brain, so the dream is not shaped by the outside world.'),
    mc('evaluation', 'Why might Activation Synthesis Theory be seen as <b>more scientific</b> than Freud\'s theory?', 'It is based on measurable brain activity, not interpretation', ['It was based on a single detailed case history', 'It can explain the hidden personal meaning of every dream a person has', 'It relies on what dreamers remember on waking'], 'Brain activity in REM can be recorded and tested. Freud\'s ideas depend on interpretation which is subjective.')
  ] };

  B['PSY-SLP-03'] = { title: 'Hormones and sleep: the pineal gland and melatonin', items: [
    mc('basics', 'Which gland releases melatonin?', 'The pineal gland', ['The pituitary gland', 'The thyroid gland', 'The adrenal gland'], 'The pineal gland releases melatonin, the hormone that makes us feel sleepy.'),
    mc('basics', 'What is the effect of melatonin on a person?', 'It makes the person feel sleepy', ['It keeps the person alert and awake', 'It speeds up dreaming', 'It raises body temperature'], 'Melatonin is a sleep-promoting hormone, so higher levels make us drowsy.'),
    mc('light and melatonin', 'How does melatonin release change when it gets dark?', 'More melatonin is released', ['Less melatonin is released', 'Melatonin release stops completely', 'Melatonin is released only during REM sleep'], 'Darkness leads the pineal gland to release more melatonin, so we feel sleepy at night.'),
    mc('light and melatonin', 'What happens to melatonin release when a person is exposed to bright light?', 'It is reduced, so the person feels more alert', ['It increases, so the person feels sleepier at midday', 'It stays the same whatever the light', 'It is released only by the SCN'], 'Light reduces melatonin release, which helps us stay alert in the day.'),
    mc('pathway', 'Which sequence correctly shows how light information leads to melatonin release?', 'Retina, then SCN, then pineal gland', ['Pineal gland, then SCN, then retina', 'SCN, then retina, then pineal gland', 'Retina, then pineal gland, then SCN'], 'Light is detected by the retina, signalled to the SCN, which passes the information to the pineal gland.'),
    mc('application', 'Kofi scrolls on a bright tablet in bed until midnight and then struggles to get to sleep. Which is the best explanation using the pineal gland and melatonin?', 'The bright screen reduced his melatonin so he felt less sleepy', ['The screen increased his melatonin so he felt much more alert at night', 'The pineal gland released hypocretin', 'His SCN stopped sending messages to the retina'], 'Bright light in the evening can suppress melatonin release, which delays feeling sleepy.'),
    mc('applications of research', 'Sunita has flown across several time zones and feels out of step with the day. Which treatment is sometimes used based on this research?', 'Melatonin supplements', ['Extra caffeine', 'Hypocretin tablets', 'Sleeping with bright lights on'], 'Melatonin supplements are sometimes used to help sleep problems and jet lag.'),
    mc('strengths', 'Which is a genuine <b>strength</b> of the melatonin explanation of sleep?', 'Melatonin levels can be measured objectively', ['It explains all sleep problems in all people', 'It is based on what people say about their dreams', 'It shows sleep is controlled only by learning'], 'Hormone levels can be measured in the body, giving scientific, testable evidence.'),
    mc('weaknesses', 'Which is a genuine <b>weakness</b> of explaining sleep using only the pineal gland and melatonin?', 'It ignores psychological causes of poor sleep such as stress', ['Melatonin levels cannot be measured at all', 'It was based on only one participant', 'It cannot explain why light affects sleep'], 'A purely biological explanation does not account for psychological causes such as stress, so it cannot explain every sleep problem.'),
    mc('common errors', 'Which statement correctly separates the pineal gland from melatonin?', 'The pineal gland is the gland; melatonin is the hormone it releases', ['The pineal gland is the hormone and melatonin is the gland that releases it', 'Both are hormones released by the SCN', 'Both are parts of the retina'], 'A gland makes and releases a hormone. Mixing these up loses marks.'),
    ms('basics', 'Which of these statements about melatonin are correct?', ['The pineal gland releases it', 'More is released in darkness', 'It makes us feel sleepy'], ['More is released in bright light', 'It keeps us awake'], 'Melatonin comes from the pineal gland, rises in darkness and promotes sleepiness. Light reduces it.'),
    mc('application', 'Hannah works nights and tries to sleep at 9 am with her curtains wide open. Why might she struggle?', 'Daylight reduces her melatonin release', ['Daylight increases her melatonin release', 'Her pineal gland releases hypocretin in the day', 'Her SCN is not connected to the eye'], 'Light lowers melatonin, so she is less sleepy when she is trying to sleep.'),
    mc('common errors', 'Zainab says: "Melatonin keeps me alert in the morning." What is wrong with this?', 'Melatonin makes us sleepy; it is reduced in light so we feel alert', ['Nothing is wrong, because melatonin is a stimulant that wakes the brain', 'Melatonin is released only in the morning', 'Melatonin is released by the retina'], 'Melatonin promotes sleep and falls in light, which is why we feel alert in the morning.'),
    mc('evaluation', 'A student says "hormones fully explain insomnia". Which is the best criticism?', 'Stress, caffeine and habits also affect sleep', ['Melatonin cannot be measured', 'The pineal gland has not been discovered', 'Light has no effect on the body'], 'Psychological and behavioural causes of poor sleep are ignored when only hormones are used as the explanation.'),
    mc('applications of research', 'A doctor advises Paolo to dim the lights and put away his phone before bed. What is the reason using melatonin?', 'Dim light allows melatonin to rise so he feels sleepy', ['Dim light makes the SCN release melatonin', 'Dim light lowers his melatonin so that he stays awake for longer', 'Phones release hypocretin'], 'Less light lets the pineal gland release more melatonin, helping sleep to start.'),
    mc('pathway', 'In the pathway from light to sleep, which structure passes the message to the pineal gland?', 'The SCN', ['The retina', 'The cortex', 'The cerebellum'], 'The retina signals the SCN, and the SCN passes the information on to the pineal gland.'),
    mc('application', 'Layla lives in a bedroom lit by a bright street light all night. Which is the most likely effect using the melatonin explanation?', 'Her melatonin release is reduced so sleep is harder', ['Her melatonin release is increased so she feels more alert', 'Her pineal gland stops working', 'Her sleep is unaffected by any light'], 'Light reduces melatonin, so she may find it harder to feel sleepy.'),
    mc('application', 'A patient\'s pineal gland releases very little melatonin at night. What problem would you expect?', 'Difficulty feeling sleepy at night', ['Excessive sleepiness during the day only', 'Sudden loss of muscle control', 'Failure to dream in REM sleep'], 'Melatonin promotes sleepiness, so very low night-time levels make sleep harder to start.'),
    mc('weaknesses', 'Jin has normal melatonin levels but still cannot sleep because of worries about money. Which evaluation point does this show?', 'Hormones do not explain every sleep problem', ['Melatonin cannot be tested', 'Light is not important for sleep', 'The pineal gland controls worries'], 'Psychological causes can disrupt sleep even when hormones are normal, so the hormone explanation is incomplete.'),
    mc('mechanism', 'Which explanation contains the hormonal mechanism?', 'Evening light lowers melatonin from the pineal gland, delaying sleepiness', ['Evening light signals the SCN, which resets the body clock to the 24-hour day', 'Evening light makes people feel emotionally uneasy', 'Evening light alters how people remember their dreams'], 'The answer must refer to the hormone and gland: light reduces melatonin from the pineal gland.'),
    ms('evaluation', 'Which of these are valid evaluation points about the melatonin explanation?', ['Melatonin can be measured objectively', 'It ignores psychological causes such as stress'], ['It is based on only a single case study of one man', 'It proves dreams have hidden meanings', 'It shows the sleep cycle lasts exactly 24 hours'], 'Objective measurement is a strength and ignoring psychological causes is a weakness. The other points belong to other topics.'),
    mc('applications of research', 'Which is a practical use of the research on melatonin?', 'Taking melatonin to help with jet lag', ['Taking hypocretin to cure insomnia', 'Using bright screens to feel sleepy', 'Sleeping with the lights on to dream more'], 'Melatonin supplements are sometimes used to help sleep problems and jet lag.')
  ] };

  B['PSY-SLP-02'] = { title: 'Bodily rhythms: circadian and ultradian', items: [
    mc('definitions', 'What is meant by a <b>bodily rhythm</b>?', 'A natural biological cycle that regulates a bodily function', ['A habit that a person gradually learns from their family and friends', 'A response to a stressful event', 'A measurement of heartbeat during exercise'], 'Bodily rhythms are natural cycles, such as the sleep-wake cycle or body temperature, that regulate functions of the body.'),
    mc('definitions', 'Which term describes a bodily rhythm that repeats about once every 24 hours?', 'Circadian', ['Ultradian', 'Dormant', 'Cataplectic'], 'Circadian rhythms last about 24 hours. Ultradian rhythms repeat more than once in 24 hours.'),
    mc('definitions', 'Which of these is an <b>ultradian</b> rhythm?', 'The cycle of NREM and REM stages through the night', ['The 24-hour sleep-wake cycle', 'The rise and fall of body temperature in a day', 'The change from daylight to darkness'], 'Ultradian rhythms repeat more than once in 24 hours, like the roughly 90-minute sleep cycle.'),
    mc('definitions', 'A researcher records a volunteer\'s body temperature every 4 hours. It peaks in the evening and is lowest in the early hours each day. What type of rhythm is this?', 'Circadian', ['Ultradian', 'Neither, because it is not related to sleep', 'Unrelated to the body clock'], 'A pattern that repeats about every 24 hours is circadian.'),
    mc('definitions', 'What does <b>ultradian</b> mean?', 'Repeating more than once in 24 hours', ['Repeating once in about 24 hours', 'Repeating less than once in 24 hours', 'Happening only during REM sleep'], 'Ultradian rhythms have a cycle shorter than a day. A cycle lasting longer than a day is not ultradian.'),
    mc('body clock', 'Where in the brain is the body clock (SCN) found?', 'The hypothalamus', ['The pineal gland', 'The retina', 'The spinal cord'], 'The suprachiasmatic nucleus (SCN) is in the hypothalamus and acts as the internal pacemaker.'),
    mc('body clock', 'The SCN is described as an <b>endogenous pacemaker</b>. What does endogenous mean?', 'It is generated from within the body', ['It is controlled by outside cues only', 'It happens only in the daytime', 'It only operates during REM sleep'], 'Endogenous means internal. External cues such as light are called zeitgebers.'),
    mc('circadian trough', 'A night security guard makes most of his errors at about 4 am. Which idea best explains this?', 'It is the circadian trough, when alertness is lowest', ['It is the ultradian peak, when alertness is at its highest', 'His pineal gland stops releasing melatonin at 4 am', 'REM sleep is longest at 4 am for everyone'], 'In the early hours of the morning, temperature and alertness are at their lowest, which increases mistakes.'),
    mc('application', 'Rafa works rotating shifts in a factory and is always tired. Which explanation using bodily rhythms is best?', 'His body clock is out of step with his working hours', ['His circadian rhythm has become ultradian', 'His SCN has moved to a different part of his brain overnight', 'His REM sleep has become a hormone'], 'Shift work puts the body clock out of step with the external day, causing tiredness and poor sleep.'),
    mc('application', 'Mina flies east across six time zones and at midday local time feels sleepy. Why?', 'Her body clock is still running on home time', ['Her ultradian rhythm has stopped', 'The new country always has fewer hours of daylight', 'Her SCN has been removed by the flight'], 'Her internal clock has not yet adjusted to the new time, so she feels sleepy when her body expects night.'),
    mc('evaluation', 'Which is a point <b>supporting</b> the idea that we have an internal body clock?', 'Siffre\'s rhythm continued without clocks or daylight', ['Everyone sleeps much better in very bright light', 'Bodily rhythms are exactly the same in all cultures', 'Shift workers always adapt completely within a single night'], 'A rhythm that continues without external cues shows an internal clock exists (Siffre\'s cave study).'),
    mc('evaluation', 'Which is a valid <b>weakness</b> of explaining sleep using internal bodily rhythms alone?', 'Rhythms are also shaped by external cues such as light', ['Rhythms cannot be seen in animals', 'Internal clocks do not exist in the brain', 'Sleep has no pattern at all'], 'Internal factors are not the whole story: external cues such as light reset the body clock.'),
    ms('definitions', 'Which of these are examples of <b>circadian</b> rhythms?', ['The sleep-wake cycle', 'The daily cycle of body temperature'], ['The cycle of sleep stages repeated through the night', 'A rhythm that repeats every 90 minutes', 'A rhythm that repeats several times in an hour'], 'Circadian rhythms run for about 24 hours. The ~90-minute sleep cycle is ultradian.'),
    { skill: 'calculation', gen: function () {
      var h = pick([6, 7.5, 9, 10.5]), n = h * 60 / 90;
      return { kind: 'num', q: 'A teenager sleeps for ' + h + ' hours. One ultradian sleep cycle through NREM and REM lasts about 90 minutes. How many complete cycles does the teenager have?', answer: n, unit: 'cycles', display: String(n), why: h + ' hours = ' + (h * 60) + ' minutes, and ' + (h * 60) + ' ÷ 90 = ' + n + ' cycles.' };
    } },
    { skill: 'calculation', gen: function () {
      var len = pick([60, 90, 120]), n = 24 * 60 / len;
      return { kind: 'num', q: 'An ultradian rhythm lasts ' + len + ' minutes. How many times does it repeat in 24 hours?', answer: n, unit: 'times', display: String(n), why: '24 hours = 1440 minutes, and 1440 ÷ ' + len + ' = ' + n + '.' };
    } },
    mc('ultradian sleep', 'Which statement explains why the sleep cycle is classed as an ultradian rhythm?', 'It repeats several times a night, each about 90 minutes long', ['It repeats once every 24 hours', 'It happens only once in the night, in the first hour of sleep', 'It lasts longer than a day'], 'The sleep cycle moves through NREM and REM stages and repeats more than once in 24 hours.'),
    mc('strengths', 'Which is a strength of explaining sleep using bodily rhythms?', 'It helps explain real problems like jet lag and shift work', ['It explains why dreams are bizarre', 'It proves light has no effect on sleep', 'It shows hormones play no part in sleep'], 'The idea of a body clock out of step with the day explains why jet lag and shift work cause tiredness and poor sleep.'),
    mc('application', 'In a sleep lab, REM sleep appears in a participant\'s recording about every 90 minutes through the night. Which type of rhythm does this show?', 'Ultradian', ['Circadian', 'Annual', 'Dormant'], 'A pattern repeating more than once in 24 hours is ultradian.'),
    mc('effects', 'Which is an effect of the body clock being out of step with the external day?', 'Tiredness and poor sleep', ['Increased alertness at night', 'Improved memory in the early hours', 'A longer circadian trough'], 'When the body clock is out of step, people feel tired and sleep poorly.'),
    mc('zeitgeber link', 'What resets the body clock each day?', 'Light', ['Cataplexy', 'Hypocretin', 'REM sleep'], 'Light is the most important external cue that resets the SCN each day.'),
    mc('evaluation', 'Kai says bodily rhythms are controlled only by the SCN and outside factors have no effect. Which evidence challenges this?', 'Light resets the body clock each day', ['The SCN is found in the hypothalamus', 'Body temperature rises and falls over a day', 'Sleep cycles last about 90 minutes'], 'Because light resets the clock, external factors do affect rhythms, so internal factors are not the whole story.'),
    ms('application', 'A traveller lands after an overnight flight crossing many time zones. Which of these are likely effects described by bodily rhythms?', ['Sleepy when it is daytime locally', 'Feeling alert at the wrong time of day'], ['Complete loss of the body clock', 'Immediate adjustment to local time', 'Falling asleep suddenly with muscle collapse'], 'Jet lag occurs because the body clock stays on home time for a while. It does not vanish and does not cause cataplexy.')
  ] };

  B['PSY-SLP-04'] = { title: 'Zeitgebers, light and Siffre\'s cave study', items: [
    mc('zeitgebers', 'What is a <b>zeitgeber</b>?', 'An external cue that resets the body clock', ['An internal pacemaker found in the hypothalamus', 'A hormone released by the pineal gland', 'A stage of sleep with fast brain waves'], 'Zeitgebers are external (exogenous) cues, such as light, that reset the body clock.'),
    mc('zeitgebers', 'Which is the most important zeitgeber for the sleep-wake cycle?', 'Light', ['Hypocretin', 'Dreaming', 'Body temperature'], 'Light entering the eye signals the SCN and keeps the sleep-wake cycle in line with the 24-hour day.'),
    ms('zeitgebers', 'Which of these are zeitgebers?', ['Daylight', 'Regular meal times', 'Social routines such as school start time'], ['The SCN in the hypothalamus', 'Melatonin released by the pineal gland'], 'Zeitgebers are external cues. The SCN and melatonin are internal.'),
    mc('Siffre procedure', 'Which describes the conditions Siffre (1975) lived in?', 'Alone in a cave for six months with no daylight or clocks', ['In a group for two weeks with normal daylight and clocks', 'In a hospital for a month with clocks and a calendar on the wall', 'In a lab for a year with a strict timetable'], 'Siffre lived alone in a cave for around six months with no external time cues.'),
    mc('Siffre results', 'What happened to Siffre\'s sleep-wake cycle in the cave?', 'It varied widely, from roughly 18 to 52 hours', ['It stayed at exactly 24 hours', 'It varied from about 10 to 14 hours', 'It stopped completely'], 'His sleep-wake cycle free-ran and varied widely. It did not stay at exactly 24 hours.'),
    mc('Siffre procedure', 'Which of these did Siffre complete while in the cave?', 'Memory tests and other tasks', ['Dream diaries for a researcher', 'Daily handwriting analysis', 'Speech assessments with visitors'], 'He did memory tests and other tasks. His memory and manual dexterity worsened during isolation.'),
    mc('Siffre results', 'Which result was found in Siffre\'s study?', 'He lost track of the date', ['His memory improved over the six months', 'He always woke at the same time each day', 'His manual dexterity became sharper'], 'Siffre lost track of the date, and his memory and manual dexterity worsened.'),
    mc('Siffre conclusion', 'What did Siffre\'s study conclude?', 'An internal clock exists, but drifts from 24 hours without zeitgebers', ['The body clock is controlled entirely by outside cues and has no internal part', 'Humans do not have a body clock', 'The body clock always runs at exactly 24 hours'], 'The sleep-wake cycle continued but drifted, so there is an internal clock which needs zeitgebers to stay at 24 hours.'),
    mc('Siffre evaluation', 'Which is a valid <b>weakness</b> of Siffre (1975)?', 'It was a case study of one man, so it is hard to generalise', ['It used far too many participants to be analysed properly', 'It had no data on sleep at all', 'It was carried out on animals'], 'Because only one person took part, findings may not apply to everyone.'),
    mc('Siffre evaluation', 'Siffre used an artificial light in the cave. Why could this affect the findings?', 'The light may itself have acted as a zeitgeber', ['It made the cave as bright as daylight all day long', 'It stopped his SCN from working', 'It proved light has no effect on sleep'], 'If switching a lamp on and off acted as a time cue, then he did not have complete isolation from zeitgebers.'),
    mc('application', 'Volunteers live in a windowless bunker for three weeks with no clocks. Based on Siffre, what would you predict?', 'Their sleep-wake cycles would drift away from 24 hours', ['Their cycles would stay at exactly 24 hours throughout the study', 'They would stop sleeping altogether', 'Their cycles would become exactly 18 hours'], 'Without zeitgebers the internal clock free-runs and drifts from 24 hours.'),
    mc('application', 'A night nurse sits in front of a bright daylight-style lamp when she wakes in the evening, to help adjust to her shifts. Which idea does this use?', 'Light acting as a zeitgeber to reset the body clock', ['Melatonin being made by the SCN', 'The ultradian cycle becoming longer', 'The circadian trough being removed'], 'Bright light is the main external cue that resets the body clock.'),
    mc('light and SCN', 'How does light influence the sleep-wake cycle?', 'Light entering the eye signals the SCN to keep the cycle in line', ['Light enters the eye and stops the pineal gland from working at all', 'Light is stored in the SCN until night-time', 'Light causes REM sleep to begin'], 'Light is detected by the eye and signalled to the SCN, which resets the body clock.'),
    mc('Siffre conclusion', 'Which statement about Siffre\'s findings is correct?', 'His cycle free-ran, showing the clock is internal but drifts', ['His cycle was fixed at 24 hours, showing zeitgebers do nothing', 'His cycle matched the outside world exactly', 'His cycle disappeared, showing there is no clock'], 'The sleep-wake rhythm continued without cues but was not 24 hours, so internal and external factors both matter.'),
    ms('Siffre results', 'Which of these are true of Siffre (1975)?', ['He lived alone underground', 'His sleep-wake cycle free-ran', 'He lost track of the date'], ['His memory improved', 'His cycle stayed at 24 hours exactly'], 'Siffre lived alone, free-ran and lost the date, while his memory and dexterity got worse.'),
    mc('Siffre evaluation', 'Why is it a problem that Siffre was one person?', 'Others might respond differently, so it cannot be generalised', ['It means the study had no data', 'It means the results cannot be valid for anyone', 'It means he was tested on animals'], 'A single case may not represent the wider population.'),
    mc('Siffre aim', 'What was the main interest of Siffre\'s cave study?', 'To see what happens to the sleep-wake cycle without time cues', ['To see how dreams are interpreted by a therapist after waking up each morning', 'To see whether melatonin tablets work', 'To compare the sleep of two countries'], 'The study looked at how a person\'s body clock behaves when isolated from daylight, clocks and calendars.'),
    { skill: 'calculation', gen: function () {
      var c = pick([25, 26]), d = pick([4, 5, 6, 8, 10]), n = (c - 24) * d;
      return { kind: 'num', q: 'A volunteer in a time-free bunker has a free-running cycle of ' + c + ' hours instead of 24. After ' + d + ' of these cycles, how many hours of real time have passed beyond ' + d + ' whole days (' + d + ' × 24 hours)?', answer: n, unit: 'hours', display: String(n), why: 'Each cycle is ' + (c - 24) + (c - 24 === 1 ? ' hour' : ' hours') + ' longer than 24, so after ' + d + ' cycles the extra time is ' + (c - 24) + ' × ' + d + ' = ' + n + ' hours.' };
    } },
    mc('internal vs external', 'Which pair correctly classes an internal and an external influence on sleep?', 'Internal: melatonin; external: light', ['Internal: light; external: melatonin', 'Internal: light; external: the SCN', 'Internal: meal times; external: the SCN'], 'Hormones and the body clock are internal; zeitgebers such as light are external. Calling light internal is a common mistake.'),
    mc('Siffre evaluation', 'Which is a strength of Siffre\'s study?', 'Isolation let researchers remove zeitgebers and watch the body clock', ['It tested hundreds of people from many different cultures and countries', 'It was a quick study that lasted only an hour', 'It proved that melatonin controls dreaming'], 'Removing time cues in a controlled setting gave detailed data about the internal clock and its effects.'),
    mc('application', 'Hana spends several weeks in a dark underground lab and finds that she goes to bed a little later each day. What does this show about the body clock?', 'It runs slightly longer than 24 hours without zeitgebers', ['It is controlled entirely by outside cues', 'It does not exist', 'It is fixed at exactly 24 hours'], 'Sleeping later each day suggests a free-running cycle which has drifted beyond 24 hours.'),
    mc('zeitgebers', 'Mo\'s family eats dinner at 6 pm every night and he finds he is sleepy at the same time each night. Which zeitgeber is shown here?', 'Meal times', ['Sunlight', 'Hypocretin', 'The ultradian rhythm'], 'Meal times and social routines are external cues that help set the body clock.')
  ] };

  B['PSY-SLP-06'] = { title: 'Freud\'s theory of dreaming', items: [
    mc('theory basics', 'In his book <i>The Interpretation of Dreams</i> (1900), how did Freud describe dreams?', 'The royal road to the unconscious', ['A random result of brainstem activity', 'A replay of the day\'s events to store memory', 'A response to light and darkness'], 'Freud believed dreams express unconscious wishes and fears in disguised form.'),
    mc('manifest content', 'What is the <b>manifest content</b> of a dream?', 'The dream as the dreamer remembers it', ['The hidden underlying meaning', 'The process that disguises meaning', 'The part of sleep with fast brain waves'], 'Manifest content is the storyline the person remembers. The hidden meaning is the latent content.'),
    mc('latent content', 'What is the <b>latent content</b> of a dream?', 'The hidden, underlying meaning', ['The images the dreamer can recall', 'Movement signals to the muscles', 'The sleep stage in which the dream occurs'], 'Latent content is the true, unconscious meaning, which is disguised.'),
    mc('dreamwork', 'What is <b>dreamwork</b>?', 'The unconscious process that disguises latent content as manifest content', ['The therapist\'s method of interpreting a client\'s dream in therapy sessions', 'The brain blocking sensory input in REM', 'The cortex making sense of random signals'], 'Dreamwork changes the hidden wishes into the disguised dream we remember.'),
    mc('manifest vs latent', 'Imani dreams she is on a boat with her sister and a lion. Which part of this dream is the manifest content?', 'The boat, the sister and the lion as she remembers them', ['A repressed fear of losing independence', 'The unconscious wish the dream expresses', 'The process of condensation'], 'The remembered images are manifest content. Any hidden meaning behind them would be latent.'),
    mc('manifest vs latent', 'A therapist tells a client that the lion in her dream stands for her fear of her domineering boss. Which part of Freud\'s theory is the therapist describing?', 'The latent content', ['The manifest content', 'Sensory blockade', 'Random activation'], 'Explaining the hidden meaning behind the images is interpreting the latent content.'),
    mc('dreamwork processes', 'Pete dreams of a single person who has his teacher\'s face and his mother\'s voice. Which dreamwork process is this?', 'Condensation', ['Displacement', 'Symbolisation', 'Secondary elaboration'], 'Condensation combines several people, ideas or feelings into one image.'),
    mc('dreamwork processes', 'Aisling is furious with her father, but in her dream she is terrified of a missing glove. Which dreamwork process is shown?', 'Displacement', ['Condensation', 'Secondary elaboration', 'Sensory blockade'], 'Displacement shifts the emotion from the real source (her father) onto something unimportant (the glove).'),
    mc('dreamwork processes', 'Omar fears losing an opportunity. In his dream, a train leaves the station without him. Which dreamwork process is this?', 'Symbolisation', ['Condensation', 'Displacement', 'Movement inhibition'], 'Symbolisation replaces an idea or feeling with a symbol, here a train standing for a missed chance.'),
    mc('dreamwork processes', 'On waking, Rena fills in the gaps in her jumbled dream so that it reads as a clear and logical story. Which dreamwork process is this?', 'Secondary elaboration', ['Condensation', 'Displacement', 'Symbolisation'], 'Secondary elaboration smooths the dream into a more coherent story.'),
    mc('purpose of dreamwork', 'According to Freud, why does the dreamwork disguise latent content?', 'The wishes are too upsetting to face directly', ['The brain has no way to store them', 'The senses are blocked in REM', 'The body must stay paralysed'], 'The wishes and fears are repressed and would be disturbing, so they appear in disguised form.'),
    mc('wish fulfilment', 'Which statement best matches Freud\'s idea of wish fulfilment?', 'Dreams express unconscious wishes and fears in disguised form', ['Dreams are random and have no meaning at all, only brain activity', 'Dreams are caused by what happened that day only', 'Dreams are caused by noise outside the bedroom'], 'Freud said dreams are a way of expressing repressed wishes.'),
    mc('strengths', 'Which is a genuine <b>strength</b> of Freud\'s theory?', 'Therapy based on it can help people understand their anxieties', ['It is based on measurable brain activity recorded using an EEG machine', 'It can be proved wrong by experiment', 'It explains why dreams occur in REM sleep'], 'Analysing dreams can help patients reflect on worries. Brain activity and REM are strengths of the biological theory instead.'),
    mc('weaknesses', 'Therapist Marcel will always find a hidden meaning whatever the client says about a dream. Which weakness does this show?', 'The interpretations are subjective and cannot be falsified', ['The theory relies on animal evidence', 'The theory cannot explain why dreams are bizarre', 'The theory was based on EEG data'], 'If any answer can be fitted to the theory, it cannot be tested or proved wrong.'),
    mc('weaknesses', 'Dreamers often forget parts of a dream or change it as they retell it. Why does this weaken Freud\'s theory?', 'Dream recall is unreliable, so the manifest content may be inaccurate', ['It shows dreams do not occur in REM sleep but only in the deepest sleep stages', 'It proves the body is paralysed in dreams', 'It means the dreamwork has no disguise'], 'The theory depends on what the person remembers, which may not match the dream.'),
    mc('alternative theory', 'Which statement would a critic use to challenge Freud\'s theory with a biological alternative?', 'Dreams come from random activation in REM sleep, not hidden wishes', ['Dreams are caused by unconscious wishes that are disguised as a story', 'Dreams come from latent content', 'Dreams are disguised by condensation'], 'Activation Synthesis Theory is the biological alternative and says dreams have no hidden meaning.'),
    ms('dreamwork processes', 'Which of these are processes of Freud\'s <b>dreamwork</b>?', ['Condensation', 'Displacement', 'Symbolisation'], ['Sensory blockade', 'Random activation'], 'Condensation, displacement, symbolisation and secondary elaboration are dreamwork. Sensory blockade and random activation belong to the biological theory.'),
    ms('evaluation', 'Which of these are valid <b>weaknesses</b> of Freud\'s theory of dreaming?', ['Interpretations are subjective', 'Dream recall is unreliable', 'It cannot be falsified'], ['It was based only on brain scans', 'It used too many brain-imaging experiments'], 'Subjectivity, unreliable recall and lack of falsifiability are common criticisms. Freud used case studies and dream reports, not brain scans or imaging experiments.'),
    mc('direction', 'In Freud\'s theory, which direction does the dreamwork operate in?', 'Latent content is changed into manifest content', ['Manifest content is changed into latent content', 'Random signals are changed into latent content', 'Latent content is blocked from the senses'], 'The dreamwork disguises latent content to produce the manifest dream.'),
    mc('application', 'Tariq has a dream about being unable to find his exam hall and wakes anxious. His analyst says the dream reveals a hidden fear of failing. Which pairing is correct?', 'Manifest: searching for the hall; latent: fear of failing', ['Manifest: fear of failing; latent: searching for the hall', 'Manifest: random signals; latent: sensory blockade', 'Manifest: dreamwork; latent: condensation'], 'The remembered dream is manifest; the underlying fear is the latent content.'),
    mc('contrast', 'What is the main difference between Freud\'s theory and Activation Synthesis Theory?', 'Freud says dreams have hidden meaning; the other says they do not', ['Freud says dreams are caused only by the brain activity of REM sleep', 'Freud says dreams are random brain signals', 'Freud says the body is paralysed in sleep'], 'Freud\'s theory is meaning-based; activation synthesis is biological.'),
    mc('manifest content', 'Which statement about manifest content is correct according to Freud?', 'It often includes people and events from recent days', ['It is always the true meaning of the dream', 'It is the same as the latent content', 'It cannot be remembered'], 'Manifest content is the remembered dream, which often uses recent events but disguises the deeper meaning.'),
    mc('application', 'Bella dreams of a staircase with a locked door at the top. Her therapist says the door stands for a feared chance she wants but avoids. Which dreamwork process is the therapist describing?', 'Symbolisation', ['Secondary elaboration', 'Condensation', 'Movement inhibition'], 'An object standing for an idea or feeling is symbolisation.')
  ] };

  B['PSY-LAN-04'] = { title: 'Types of non-verbal communication', items: [
    mc('definitions', 'Which of these is a form of non-verbal communication?', 'A raised eyebrow showing surprise', ['A telephone call', 'A written text message sent to a friend', 'A shouted instruction'], 'Non-verbal communication sends messages without spoken or written words. Calls, texts and shouting use words.'),
    mc('definitions', 'What is meant by <b>non-verbal communication</b>?', 'Sending messages without spoken or written words', ['Sending messages only by writing', 'Speaking very quietly to a friend without raising your voice', 'Sending messages to animals'], 'Non-verbal communication uses the face, eyes, posture and gestures instead of words.'),
    mc('facial expressions', 'Beth reads her exam result and the corners of her mouth turn downwards. What emotion does her facial expression most likely show?', 'Sadness or disappointment', ['Happiness', 'Excitement', 'Pride'], 'A downturned mouth communicates sadness. Smiling would show happiness.'),
    mc('facial expressions', 'Leo hears a loud bang and his eyebrows shoot up and his eyes open wide. What emotion does his face most likely communicate?', 'Surprise', ['Boredom', 'Contentment', 'Calm'], 'Raised eyebrows and wide eyes are a typical facial expression of surprise.'),
    mc('eye contact', 'During a conversation, Maya\'s pupils widen and she keeps looking at the speaker. What might this non-verbal signal show?', 'Interest or attraction', ['Sadness or boredom', 'Anger', 'Discomfort'], 'Dilated pupils and maintained eye contact can show interest or attraction.'),
    mc('eye contact', 'When his teacher asks about a missing homework, Dan looks at the floor and will not meet her gaze. What might this show?', 'Discomfort', ['Pride', 'Attraction', 'Confidence'], 'Looking away is a way of showing discomfort or sadness.'),
    mc('posture', 'Ali leans forward with open arms while listening to a friend. What does this posture most likely signal?', 'Interest and openness', ['Boredom and anger', 'Disgust', 'Fear'], 'An open posture leaning towards a speaker signals interest.'),
    mc('posture vs gesture', 'Which example is a <b>posture</b>, not a gesture?', 'Standing with arms tightly crossed', ['Waving goodbye to a friend at the station', 'Pointing at a book', 'Nodding the head'], 'A posture is how the body is held. Waving, pointing and nodding are movements that carry meaning, so they are gestures.'),
    mc('posture vs gesture', 'Which example is a <b>gesture</b>?', 'Pointing to the door to show where to go', ['Slumping in a chair', 'Sitting for a long time with legs crossed', 'Standing very tall'], 'Gestures are movements of the hands or body that carry meaning, such as pointing.'),
    mc('definitions', 'What is meant by <b>gestures</b>?', 'Movements of the hands or body that carry meaning', ['The way the body is held while sitting', 'The distance kept between two people', 'The sounds a person makes when they are speaking to others'], 'A gesture is a movement used to communicate, such as a wave or thumbs up.'),
    mc('definitions', 'Which description of <b>posture</b> as body language is correct?', 'How the body is held, such as slouching or sitting up', ['A hand movement used to show someone which way they should go', 'A change in the face to show emotion', 'The look in someone\'s eyes'], 'Posture is the position in which the body is held.'),
    mc('facial expressions', 'Which facial expression most clearly communicates happiness?', 'Smiling with raised cheeks', ['Frowning with lowered eyebrows', 'Mouth corners turned downwards', 'Lips pressed tightly together'], 'A smile with raised cheeks communicates happiness. A downturned mouth shows sadness and a frown shows anger or worry.'),
    mc('contradiction', 'Chloe says "I\'m fine, really" but she is slumped with her head down and eyes on the floor. Which message will most people believe?', 'The non-verbal message that she is upset', ['The spoken message that she is fine', 'Neither, as non-verbal signals are meaningless', 'Both are equally believed in every case'], 'People often trust non-verbal signals more when they clash with the words.'),
    ms('examples', 'Which of these are forms of non-verbal communication?', ['Smiling', 'Giving a thumbs up', 'Leaning forward in a chair'], ['Sending a text message', 'Making a phone call'], 'Smiling, thumbs up and posture use no words. Texts and calls rely on words.'),
    ms('examples', 'Which of these are examples of <b>facial expressions</b> or <b>eye contact</b>?', ['Frowning', 'Staring directly at someone', 'Raising the eyebrows'], ['Folding the arms', 'Waving the hand'], 'Frowning, eye contact and eyebrows involve the face and eyes. Folding arms is a posture and waving is a gesture.'),
    mc('cultural differences', 'A traveller gives a thumbs up to a shopkeeper, who looks offended. Which idea about non-verbal communication does this show?', 'Gestures can mean different things in different cultures', ['Gestures are the same everywhere', 'Gestures are always understood as insults in other cultures', 'Non-verbal communication has no meaning'], 'Cultural differences mean a gesture may be friendly in one place and rude in another.'),
    mc('describe vs identify', 'Which answer earns the mark for explaining how a facial expression communicates emotion?', 'Her smile shows she is happy', ['She is smiling', 'Her mouth moves upward', 'She turns her head'], 'A full answer says what the expression communicates (happiness), not just what the face is doing.'),
    mc('application', 'In an interview, a candidate avoids eye contact and keeps fidgeting with his pen. What might the interviewer take from these signals?', 'The candidate is nervous or uncomfortable', ['The candidate is overconfident', 'The candidate is bored by the questions', 'The candidate is attracted to the interviewer'], 'Looking away and fidgeting are non-verbal signals of discomfort or nervousness.'),
    mc('application', 'Nina crosses her arms and turns her body away from a speaker. Which type of non-verbal communication is this mainly?', 'Posture', ['Eye contact', 'Facial expression', 'Gesture'], 'Body position (arms crossed, body turned) is posture, which is a type of body language.'),
    mc('statements', 'Which statement about non-verbal communication is correct?', 'It can be used without words and can contradict what is said', ['It can only be used with spoken words', 'It is understood in exactly the same way in every culture around the world', 'It never shows emotions'], 'NVC works without words and may differ from the spoken message; its use and meaning vary between cultures.'),
    mc('application', 'Sofia holds her hand up with the palm facing a noisy class. Which type of non-verbal communication is this and what does it communicate?', 'A gesture asking for quiet', ['A posture showing happiness', 'A facial expression of surprise', 'Eye contact showing attraction'], 'A hand movement that carries a meaning is a gesture.'),
    mc('application', 'Reece says he is delighted with a gift, but his smile does not reach his eyes and he glances away. What is the best interpretation?', 'His non-verbal signals suggest he is not really delighted', ['He is clearly delighted', 'He is lying about every gift he is given', 'Non-verbal signals cannot tell us anything'], 'When words and non-verbal signals clash, people tend to trust the non-verbal signal.')
  ] };

  B['PSY-LAN-03'] = { title: 'Human language vs animal communication', items: [
    mc('Aitchison', 'How many criteria (features) of language did Aitchison (1983) list?', '10', ['2', '25', '50'], 'Aitchison listed 10 criteria of language to compare human language with animal communication.'),
    mc('displacement', 'What is meant by <b>displacement</b>?', 'Communicating about things that are not here and now', ['Using symbols such as words with agreed and shared meanings', 'Making endless new sentences', 'Taking turns in a conversation'], 'Displacement allows talk about the past, the future or imaginary events.'),
    mc('semanticity', 'What is meant by <b>semanticity</b>?', 'Using symbols such as words that have shared, agreed meanings', ['Talking about past and future events', 'Understanding that word order and grammar change meaning in a sentence', 'Sending warning sounds'], 'Words are symbols whose meanings are agreed, including abstract ideas.'),
    mc('structure dependence', 'Which pair of sentences best shows <b>structure dependence</b>?', '"The cat chased the mouse" and "The mouse chased the cat"', ['"Hello" and "Goodbye"', '"I will go tomorrow" and "I went yesterday"', '"Justice" and "freedom"'], 'Word order and grammar change the meaning of the sentence.'),
    mc('creativity', 'A child says, "The purple elephant sneezed on my sandwich", a sentence she has never heard. Which feature of language is this?', 'Creativity', ['Turn-taking', 'Displacement', 'Semanticity'], 'Creativity is making endless new sentences that have not been heard before.'),
    mc('shared features', 'Which feature of language is shared by humans and animals?', 'Turn-taking', ['Displacement', 'Structure dependence', 'Creativity'], 'Turn-taking occurs in animal communication too. Displacement, semanticity, structure dependence and creativity are found only in humans.'),
    ms('human only', 'Which of these features are found only in human language?', ['Semanticity', 'Displacement', 'Creativity'], ['Turn-taking', 'Using sounds to communicate'], 'Turn-taking and sounds are shared with animals, while the first three features are found only in humans.'),
    mc('application', 'Priya texts her sister: "Remember our holiday last year? Let\'s go again next summer." Which feature of language does this show?', 'Displacement', ['Turn-taking', 'Structure dependence', 'Facial expression'], 'She is talking about past and future events, not things present now.'),
    mc('application', 'Kurt\'s dog whines at the door when it wants to go outside. Which statement describes this communication?', 'The dog is communicating a need using sound', ['The dog is using displacement', 'The dog is using structure dependence', 'The dog is not communicating at all'], 'Animals communicate needs, warnings and emotions using sounds and body signals.'),
    mc('differences', 'Which statement gives a <b>difference</b> between human and animal communication?', 'Humans can discuss events in the past and future', ['Both can use sounds to communicate', 'Both can use facial expressions to show their emotions', 'Both can send warnings'], 'Displacement is a human feature; the other options are similarities.'),
    mc('similarities', 'Which statement gives a <b>similarity</b> between human and animal communication?', 'Both use sounds, facial expressions and body signals', ['Both can talk about imaginary events', 'Both can create endless new sentences from a set of words', 'Both depend on word order'], 'Both species groups communicate needs, warnings and emotions with sounds, facial expressions and body signals.'),
    mc('common errors', 'Which statement is correct?', 'Animals do communicate, but without some features of human language', ['Animals cannot communicate at all', 'Animals have every single feature of human language, including grammar', 'Animals use only written signs'], 'Animals communicate, but human language has extra features such as displacement and creativity.'),
    mc('application', 'In a conversation, Dev waits for Eli to finish before he speaks. Which feature is this, and is it shared with animals?', 'Turn-taking, which is shared with animals', ['Displacement, which humans alone have', 'Creativity, which humans alone have', 'Structure dependence, which animals share'], 'Turn-taking is a feature which occurs in animal communication as well as human conversation.'),
    mc('application', 'A teacher explains the word "freedom", an idea you cannot point at. Which feature of language does this use?', 'Semanticity', ['Turn-taking', 'Displacement', 'Structure dependence'], 'Semanticity is using words as symbols with agreed meanings, including abstract ideas.'),
    mc('application', 'Lina says "Dog bites man" and Tom says "Man bites dog". The meanings differ although the words are the same. Which feature explains this?', 'Structure dependence', ['Turn-taking', 'Displacement', 'Creativity'], 'The word order changes the meaning, which is structure dependence.'),
    mc('application', 'A grandfather tells his grandchild a story about a dragon that lives on a cloud. Which feature does this best show?', 'Displacement', ['Turn-taking', 'Structure dependence', 'Warning calls'], 'Talking about an imaginary event that is not present is displacement.'),
    mc('similarities', 'Many animals give an alarm call when they see danger. Which similarity with humans does this show?', 'Both can communicate warnings', ['Both can discuss the future', 'Both use grammar', 'Both can invent new sentences'], 'Humans also warn each other of danger by shouting or gesturing.'),
    mc('definitions', 'What is meant by <b>creativity</b> as a feature of language?', 'Making endless new sentences from words', ['Talking about the past and future', 'Using the same call each time', 'Taking turns while speaking'], 'Creativity means we can produce an unlimited number of new sentences.'),
    mc('Aitchison', 'What did Aitchison (1983) use her criteria for?', 'To compare human language with animal communication', ['To explain why people dream', 'To measure the length of sleep cycles', 'To judge how loud speech is'], 'The criteria are a checklist of features used to compare human and animal communication.'),
    mc('human only', 'Which example would a psychologist NOT treat as evidence of a human-only feature?', 'A parrot calling out when it wants food', ['A child describing what she will do next week', 'A man making up a joke he has never heard', 'A woman explaining what happened last year'], 'Calling for food communicates a present need; talking about next week or last year (displacement) or creating new jokes (creativity) is human-only.'),
    mc('differences', 'Which is a difference between a child\'s speech and a dog\'s barking?', 'The child can say new sentences about things that are not present', ['Both can only react to what is happening around them at that moment', 'Both depend on the order of words', 'Both are taught to use words'], 'Humans have creativity and displacement; a bark responds to the here and now.'),
    mc('application', 'Greta shouts "Careful!" when a car approaches, and the family dog barks to warn of a stranger. What do these two examples show?', 'Humans and animals both communicate warnings', ['Both are examples of displacement and creativity', 'Both show structure dependence', 'Both show creativity'], 'Both humans and animals warn others of danger; this is a similarity, not a human-only feature.')
  ] };

  B['PSY-LAN-07'] = { title: 'Yuki et al. (2007): eyes or mouth?', items: [
    mc('sample', 'Who were the participants in Yuki et al. (2007)?', 'Japanese and American students', ['Japanese and Chinese school children', 'American and British adults', 'Japanese and British workers'], 'The study compared Japanese and American students.'),
    mc('sample', 'How many American students took part in Yuki et al. (2007)?', '118', ['95', '85', '213'], 'There were 118 American and 95 Japanese students.'),
    { skill: 'calculation', kind: 'num', q: 'In Yuki et al. (2007) there were 95 Japanese and 118 American students. How many students took part altogether?', answer: 213, unit: 'students', display: '213', why: '95 + 118 = 213 students.' },
    mc('procedure', 'What did participants do in Yuki et al. (2007)?', 'They rated how happy or sad faces (emoticons) looked', ['They wrote essays about their own emotions and feelings', 'They were interviewed about family life', 'They memorised lists of words'], 'Participants rated emoticons and edited faces with different eyes and mouths on a happiness scale.'),
    mc('results', 'Which finding is correct for the <b>Japanese</b> participants?', 'They gave more weight to the eyes when judging emotion', ['They gave much more weight to the mouth than to the eyes', 'They ignored both eyes and mouth', 'They relied on gestures'], 'Japanese participants relied more on the eyes. Americans relied more on the mouth.'),
    mc('results', 'Which finding is correct for the <b>American</b> participants?', 'They gave more weight to the mouth when judging emotion', ['They gave more weight to the eyes', 'They gave equal weight to the eyes and to the tone of voice', 'They were not able to rate emotions'], 'Americans were more influenced by the mouth.'),
    mc('explanation', 'How did Yuki et al. explain the difference between the two cultures?', 'In Japan people hide emotions, and the eyes are harder to control', ['Americans have better eyesight than Japanese people, so use the mouth', 'Japanese faces have no mouth expressions', 'Americans are taught to look only at eyes'], 'Japanese people are encouraged to control emotion, and the eyes are harder to control so are trusted more.'),
    mc('application', 'Hiroshi (from Japan) and Jack (from the USA) each look at a message with a smiling mouth but sad eyes. According to Yuki et al., who is more likely to judge the sender\'s mood from the eyes?', 'Hiroshi', ['Jack', 'Both, equally', 'Neither, because culture is irrelevant'], 'Japanese participants gave more weight to the eyes, so Hiroshi is more likely to read the sad eyes.'),
    mc('application', 'Elliot (from the USA) and Kenji (from Japan) both see a photo of a friend with a big smile but flat, neutral eyes. According to Yuki et al., which prediction is best?', 'Elliot will rate her as happier than Kenji does, because he gives more weight to the mouth', ['Elliot will rate her as less happy than Kenji does, because he gives more weight to the eyes', 'Kenji will rate her as happier than Elliot does, because he gives more weight to the mouth', 'Elliot and Kenji will give the same rating, because culture does not change which cue is used'], 'American participants gave more weight to the mouth and Japanese participants more to the eyes, so the smile counts for more with Elliot than with Kenji.'),
    mc('evaluation', 'Which is a valid <b>weakness</b> of Yuki et al. (2007)?', 'Student samples and emoticons may not reflect real-life judgements', ['The study used only one participant from each of the countries', 'The study did not compare two cultures', 'The study was done on animals'], 'Students are not typical of everyone and drawn faces are less realistic than real people, which limits generalisation.'),
    mc('conclusion', 'What is the main conclusion of Yuki et al. (2007)?', 'Cultures differ in which facial cues they use to recognise emotion', ['All cultures read emotion from exactly the same facial cue as each other', 'Emotions cannot be read from faces', 'Eyes are always more important than mouths'], 'The Japanese used the eyes more and Americans used the mouth more, so cultural differences exist.'),
    mc('errors', 'Which statement about the study is correct?', 'Japanese participants relied on the eyes more than American participants', ['American participants relied on the eyes more than Japanese participants', 'Both groups relied only on the mouth', 'Japanese participants were children'], 'Reversing the result is a common error: Japan = eyes; USA = mouth.'),
    ms('facts', 'Which of these are true of Yuki et al. (2007)?', ['The sample was students', 'Japanese participants gave more weight to the eyes', 'American participants gave more weight to the mouth'], ['The sample was 200 children from Europe', 'American participants gave more weight to the eyes'], 'Students from Japan and the USA took part, with the eyes/mouth difference described.'),
    mc('methods', 'Why did Yuki et al. use emoticons whose eyes and mouths could be changed separately?', 'To see which feature, the eyes or the mouth, drove the happiness rating', ['To let participants hear the emotion in each voice', 'To make sure all participants came from one country', 'To remove the need for any participant to give a rating'], 'Changing the eyes and mouth independently shows how much weight each cue carries when people judge emotion.'),
    mc('methods', 'In Yuki et al., what was the participants\' <b>dependent variable</b>?', 'The rating of how happy each face looked', ['The country they lived in', 'The shape of the eyes and mouth on the emoticon', 'The number of students tested'], 'Participants rated happiness. Culture and eye/mouth shape were the independent variables.'),
    mc('methods', 'Yuki et al. compared Japanese with American students. Which is the independent variable that tested for cultural difference?', 'The nationality of the participants', ['The happiness rating', 'The time taken to finish the whole task', 'The number of emoticons'], 'The participants\' culture was compared, so it is the variable manipulated by selection.'),
    mc('evaluation', 'Why might rating emoticons not be a fully valid way to study how people judge emotion?', 'Real faces are more complex and move, unlike emoticons', ['Emoticons are never seen by students', 'Participants were forced to take part against their will', 'Emotion cannot be rated at all'], 'Lack of realism limits ecological validity.'),
    mc('evaluation', 'Why is it a problem that all the participants were students?', 'Students may not represent people of other ages', ['Students cannot see the details of faces very well', 'Students always rate every face they see as happy', 'Students come from one culture only'], 'The sample may not generalise to the wider populations of Japan and the USA.'),
    mc('application', 'A business trainer tells staff: "When dealing with colleagues from Japan, pay close attention to the eyes." Which finding supports this advice?', 'Japanese participants gave more weight to the eyes', ['American participants gave more weight to the eyes', 'Japanese participants ignored facial expressions', 'Both groups relied on gestures'], 'The study found Japanese participants used the eyes more when judging emotion.'),
    mc('explanation', 'Why are the eyes seen as a more trusted cue in Japan, according to the explanation in the study?', 'They are harder to control than the mouth', ['They are bigger and easier to see than the mouth', 'They are used to speak', 'They change colour to show the emotion a person feels'], 'In a culture where hiding emotion is encouraged, the eyes are the less controllable and so more honest cue.'),
    { skill: 'calculation', gen: function () {
      var j = pick([40, 50, 60]), a = pick([70, 80, 90]), p = R.roundDp(j / (j + a) * 100, 1);
      return { kind: 'num', q: 'A replication of an eyes-and-mouth study tests ' + j + ' Japanese and ' + a + ' American students. What percentage of all the students were Japanese? Give your answer to 1 decimal place.', answer: p, unit: '%', tol: 0.1, display: String(p), why: 'Total = ' + j + ' + ' + a + ' = ' + (j + a) + '. Percentage = ' + j + ' ÷ ' + (j + a) + ' × 100 = ' + p + '%.' };
    } },
    mc('conclusion', 'Which of these is a conclusion that can be drawn from the study?', 'Cultural background affects how emotion is read from the face', ['Emotion is identified in exactly the same way by people worldwide', 'The mouth is always the better cue', 'Culture does not affect facial expression'], 'The different weightings of eyes and mouth show cultural differences in reading emotion.'),
    mc('application', 'Maya says "People from every country read emotion in faces in exactly the same way." Which study finding challenges this?', 'The two cultures used different facial cues', ['Both groups were made up of university students', 'The study used emoticons', 'The sample was about 200 people'], 'Differences in use of the eyes and mouth show that culture affects emotion reading.')
  ] };

  B['PSY-LAN-01'] = { title: 'How language and thinking develop: Piaget vs Vygotsky', items: [
    mc('Piaget', 'According to Piaget (1950), how are thought and language related?', 'Thinking develops first and language follows', ['Language develops first and thinking follows', 'They are separate systems that never join', 'They develop at exactly the same time'], 'Piaget argued that representational thinking precedes language, so a child can only name what they already understand.'),
    mc('Vygotsky', 'According to Vygotsky (1981), how are thought and language related?', 'They begin as separate systems that join at about 2-3 years', ['Thinking always has to come before any language is learned at all', 'Language comes first and creates thought', 'They are the same system from birth'], 'Vygotsky said pre-linguistic thought and pre-intellectual language begin separately and merge at around 2-3 years old.'),
    mc('representational thinking', 'What is meant by <b>representational thinking</b>?', 'Letting symbols such as words stand for real objects', ['Making sounds and gestures without thinking about them', 'Talking aloud to oneself while playing alone', 'Learning language from parents only'], 'Piaget says this ability must exist before a child can use language.'),
    mc('schema', 'Eden can name "cat" and "dog" but cannot name a ferret she has never seen. Which Piaget idea explains this?', 'She has no schema for a ferret, so she cannot name it', ['Her pre-intellectual language is too strong', 'Her thought and language have joined', 'She is using inner speech'], 'A child with no schema for an object cannot name it, as understanding comes before naming.'),
    mc('egocentric speech', 'Four-year-old Sam says aloud, "Now I put the red block here", while building alone. Which Piaget term describes this?', 'Egocentric speech', ['Pre-intellectual language', 'Representational thinking', 'Pre-linguistic thought'], 'Egocentric speech is a running commentary not aimed at a listener.'),
    mc('pre-linguistic thought', 'An eight-month-old reaches and points to a toy that is out of reach. Which Vygotsky idea does this show?', 'Pre-linguistic thought', ['Pre-intellectual language', 'Inner speech', 'Egocentric speech'], 'The baby shows thinking and problem-solving before it has words.'),
    mc('pre-intellectual language', 'Nine-month-old Ravi repeats "ba-ba-ba" throughout the day with no meaning behind it. Which Vygotsky idea does this show?', 'Pre-intellectual language', ['Pre-linguistic thought', 'Representational thinking', 'Schemas'], 'Babbling is using sounds without thought behind them.'),
    mc('merging', 'According to Vygotsky, what happens at around 2-3 years of age?', 'Thought and language join, so speech helps thinking', ['Babies learn to babble for the first time', 'Children stop thinking altogether for a while', 'Language that was learned is lost again'], 'After the systems join, speech becomes a tool of thought and later turns into inner speech.'),
    mc('inner speech', 'What does Vygotsky say speech eventually turns into?', 'Inner speech', ['Egocentric babble', 'Pre-intellectual language', 'Schemas'], 'As thought and speech merge, speech used aloud becomes silent inner speech.'),
    ms('Piaget', 'Which of these are ideas from <b>Piaget</b>?', ['Representational thinking must come before language', 'Children use egocentric speech', 'Schemas affect what a child can name'], ['Thought and language start as two separate systems', 'Babbling is pre-intellectual language'], 'The first three are Piaget; separate systems and pre-intellectual language are from Vygotsky.'),
    mc('application', 'Isla understands what a bicycle is and then uses the word "bike". Which theory best matches this?', 'Piaget, as understanding comes before the word', ['Vygotsky, as language comes before any thinking', 'Neither, as language is unrelated to thinking', 'Piaget, as babbling comes before understanding'], 'Piaget says a child names what they already understand.'),
    mc('application', 'A toddler talks to herself while pushing a toy car, "Vroom, car go fast". Which Vygotsky explanation fits this?', 'Speech has joined with thought and helps her think', ['It is pre-linguistic thought, thinking without words', 'It is pre-intellectual language, sounds without thought', 'She has no thinking yet because she is so young'], 'Vygotsky says that after 2-3 years, speech serves thought.'),
    mc('evaluation', 'Which is a strength of Vygotsky\'s explanation compared with Piaget\'s?', 'It can explain babbling and the problem-solving of babies before words', ['It says babies cannot think at all until they have learned to talk', 'It requires a schema for every word', 'It proves children are always egocentric'], 'Vygotsky has terms for sounds without thought (pre-intellectual) and thought without words (pre-linguistic).'),
    mc('evaluation', 'Which is a strength of Piaget\'s explanation?', 'It explains why children cannot name what they do not understand', ['It explains why babies babble without meaning', 'It explains why speech later turns into inner speech in children', 'It shows thought and language are separate'], 'It fits observations that naming follows understanding.'),
    mc('evaluation', 'Which is a weakness of Piaget\'s explanation?', 'It does not explain why babies babble before having any thoughts', ['It cannot explain why young children use egocentric speech aloud', 'It claims that language precedes thought', 'It cannot explain what a schema is'], 'Babbling does not match the idea that all language follows thought.'),
    mc('common errors', 'Which theory says thinking and language are two independent systems at first?', 'Vygotsky', ['Piaget', 'Both Piaget and Vygotsky', 'Neither theory'], 'Piaget thought thinking comes first; Vygotsky saw two separate systems that join.'),
    mc('AO classification', 'In a 9-mark answer, which sentence is <b>evaluation</b> of Piaget\'s theory?', 'A weakness is that babies babble before they have thoughts to name', ['Piaget said that thinking develops before language does in children', 'Egocentric speech is a running commentary', 'A schema is a mental package of knowledge'], 'Evaluation judges the theory (strength, weakness, comparison). The other sentences describe it.'),
    mc('AO classification', 'Which sentence is <b>application</b> to the scenario of a toddler who cannot name a cow she has never seen?', 'She has no schema for a cow so, to Piaget, she cannot name it', ['Piaget proposed that thinking develops before language in all children', 'A weakness of Piaget is that babbling is unexplained', 'Schemas are mental packages of knowledge'], 'Application links the theory to the child in the scenario.'),
    mc('judgement', 'Which conclusion is a supported judgement?', 'Vygotsky explains babbling better, as he separates thought and language at first', ['Vygotsky is better because he is more famous than Piaget', 'Piaget is wrong because all children learn to talk', 'Both are the same, so no more needs to be said'], 'A supported judgement gives a reason from the evidence.'),
    mc('application', 'Aisha is 18 months old and says "teddy" and "car" for objects she knows well but stays silent for objects she has not seen. Which theory is this a better fit for?', 'Piaget', ['Vygotsky', 'Neither, as it shows no thinking', 'Both, as they said the same'], 'Piaget: naming follows understanding, so she names only what she knows.'),
    mc('definitions', 'What is meant by <b>pre-linguistic thought</b>?', 'Thinking that happens before a child has words', ['Words used by a child without thought', 'Talking aloud to oneself when playing', 'Learning the grammar rules of a language'], 'Pre-linguistic thought is problem-solving before language, such as pointing or reaching.'),
    mc('definitions', 'What is meant by <b>pre-intellectual language</b>?', 'Sounds or words used without thought behind them', ['Thinking that happens before having any words', 'Silent speech that is used in the head', 'A mental package of knowledge about objects'], 'Babbling is an example of language without thought.')
  ] };

  B['PSY-LAN-02'] = { title: 'Does language shape how we see the world?', items: [
    mc('relativism', 'What is meant by <b>linguistic relativism</b>?', 'The language you speak influences how you think about the world', ['The language you speak decides what you can think', 'The world around you decides which language you will learn to speak', 'Everyone thinks in exactly the same way'], 'Relativism is the weak version of the Sapir-Whorf hypothesis: language influences thought.'),
    mc('determinism', 'What is meant by <b>linguistic determinism</b>?', 'Language decides what a person is able to think', ['Language only slightly influences thinking', 'Thinking has no link to language', 'Language is learned from thinking about the world'], 'Determinism is the strong version: with no word for something you cannot think about it.'),
    mc('application', 'In one language there is no word for "tomorrow", and speakers are said to be unable to think about the future at all. Which view does this match?', 'Linguistic determinism', ['Linguistic relativism', 'Neither view', 'Piaget\'s view'], 'Language is claimed to decide what can be thought, which is determinism.'),
    mc('application', 'A language has three different words for kinds of rain. Its speakers notice differences in rain faster than English speakers, but English speakers can learn to see them too. Which view does this fit?', 'Linguistic relativism', ['Linguistic determinism', 'Piaget\'s view', 'Vygotsky\'s view'], 'Language influences attention to the world but does not stop other people from thinking about it: relativism.'),
    mc('Boroditsky', 'Which two groups did Boroditsky (2001) compare?', 'English and Mandarin speakers', ['English and French speakers', 'Mandarin and Japanese speakers', 'English and Spanish speakers'], 'She compared how English and Mandarin speakers think about time.'),
    mc('Boroditsky', 'How do English speakers mostly talk about time?', 'Horizontally, e.g. ahead, behind, forwards and back', ['Vertically, e.g. up for earlier and down for later', 'Using colours', 'Using only numbers'], 'English mostly uses horizontal terms; Mandarin also uses vertical ones.'),
    mc('Boroditsky', 'In Mandarin, which words are used for talking about earlier and later events, as well as horizontal ones?', 'Vertical words such as up for earlier and down for later', ['Words describing colours, shapes and sizes of the objects', 'Words for temperature', 'Only words for numbers'], 'Mandarin also uses vertical terms: up for earlier and down for later.'),
    mc('Boroditsky procedure', 'In Boroditsky\'s study, what came before the true or false question about time?', 'A horizontal or vertical prime', ['A memory test using lists of words', 'An EEG recording of brain activity', 'A dream diary kept for a week'], 'Participants saw a spatial prime (a picture statement) and then answered a true or false question about time.'),
    mc('Boroditsky procedure', 'Which statement is an example of a <b>vertical</b> prime?', 'The black ball is above the white ball', ['The black ball is ahead of the white ball', 'The black ball is behind the white ball', 'The black ball is bigger than the white ball'], 'Above and below describe a vertical relation; ahead and behind are horizontal.'),
    mc('Boroditsky results', 'After a vertical prime, who answered the time question faster?', 'Mandarin speakers', ['English speakers', 'Both groups equally', 'Neither group'], 'Mandarin speakers answered faster after vertical primes and English speakers after horizontal ones.'),
    mc('Boroditsky results', 'After a horizontal prime, who answered the time question faster?', 'English speakers', ['Mandarin speakers', 'Both groups equally', 'Nobody, as primes had no effect'], 'English speakers think about time horizontally, so horizontal primes helped them.'),
    mc('Boroditsky conclusion', 'What did Boroditsky (2001) conclude?', 'The language you speak shapes how you think about time', ['Language is irrelevant to thought', 'Time is thought of in exactly the same way in all languages', 'Language decides what can be thought'], 'The result supports linguistic relativism, because language influenced thinking about time.'),
    mc('Everett', 'Everett (2005) studied the Pirahã tribe, which has words only for one, two and "many". Which view did this support?', 'Linguistic determinism', ['Linguistic relativism', 'Piaget\'s view', 'Neither view'], 'They struggled to match exact larger quantities, which supports the idea that language limits thought.'),
    mc('application', 'A prediction: "Speakers of a language with only words for one, two and many will find it hard to match exact larger quantities." Which view makes this prediction?', 'Linguistic determinism', ['Linguistic relativism', 'No view makes it', 'Both views to the same extent'], 'Determinism says language limits what can be thought.'),
    mc('evaluation', 'English speakers can learn the German word "schadenfreude", then use it to think about a feeling they had no word for. Which view does this challenge?', 'Linguistic determinism', ['Linguistic relativism', 'Both views equally', 'Neither view'], 'If new words and concepts can be learned, language does not decide what can be thought.'),
    ms('relativism', 'Which of these statements fit <b>linguistic relativism</b>?', ['Language influences thought', 'It is the weak version of the Sapir-Whorf hypothesis', 'People can learn to think about things beyond their language'], ['Language decides what can be thought', 'People with no word for something cannot think about it'], 'Relativism says language influences thinking; the last two are determinism.'),
    ms('Boroditsky', 'Which of these are true of Boroditsky (2001)?', ['She compared English and Mandarin speakers', 'She used spatial primes', 'Mandarin speakers did better after vertical primes'], ['She compared Mandarin and Japanese speakers', 'English speakers did better after vertical primes'], 'The study used English and Mandarin speakers; Mandarin is faster with vertical primes and English with horizontal.'),
    mc('evaluation', 'Which is a valid <b>strength</b> of Boroditsky\'s study?', 'It used controlled primes and measured response times', ['It studied thousands of tribes across the world', 'It used interviews about dreams', 'It watched people in everyday life without them knowing'], 'Controlled procedures and measurable results give objective data.'),
    mc('evaluation', 'Which is a valid <b>weakness</b> of Boroditsky\'s study?', 'Only two languages were tested, so it may not generalise', ['It had no way to measure the results it collected from people', 'It used animals instead of people', 'It did not test any language'], 'Testing just English and Mandarin speakers limits how far the conclusions can be applied.'),
    mc('evaluation', 'A researcher notes that Pirahã people might struggle with exact numbers because of their way of life, not their language. What problem with the evidence is this?', 'Language may not be the cause of the difference', ['The study had too many participants', 'It proves that language completely decides thought', 'It proves that thought decides language'], 'Culture or lifestyle could be the cause, so it is difficult to say that language caused the difference.'),
    mc('application', 'A language has no past tense, yet its speakers can accurately describe what happened last week. Which view does this challenge?', 'Linguistic determinism', ['Linguistic relativism', 'Neither, as the language lacks words', 'Both equally'], 'If speakers can think about the past without grammar for it, language does not decide what they can think.'),
    mc('judgement', 'Which is a <b>supported conclusion</b> about the two views?', 'Relativism has more support, as Boroditsky shows influence and new words can be learned', ['Determinism is correct because the Pirahã tribe exists and counts differently', 'Relativism is correct because everyone in the world speaks the same language', 'Neither can be judged because both views are only about animals'], 'A supported judgement uses evidence (Boroditsky, new words) to prefer one view.'),
    mc('direction', 'In linguistic relativism, which direction does the influence go?', 'Language shapes thought', ['Thought shapes language only', 'The world shapes language only', 'There is no influence'], 'Reversing the theory is a common error: relativism says language influences thinking.')
  ] };
})();
